import itertools
trip8 = [(i, j, k) for i in (1,2) for j in (3,4) for k in (5,6)]
cop = [[(1, 3, 5), (1, 3, 6), (1, 4, 5), (1, 4, 6)],[(1, 3, 5), (1, 3, 6), (2, 3, 5), (2, 3, 6)],[(1, 3, 5), (1, 3, 6), (2, 4, 5), (2, 4, 6)],[(1, 3, 5), (1, 4, 5), (2, 3, 5), (2, 4, 5)],[(1, 3, 5), (1, 4, 5), (2, 3, 6), (2, 4, 6)],[(1, 3, 5), (1, 4, 6), (2, 3, 5), (2, 4, 6)],[(1, 3, 6), (1, 4, 5), (2, 3, 6), (2, 4, 5)],[(1, 3, 6), (1, 4, 6), (2, 3, 5), (2, 4, 5)],[(1, 3, 6), (1, 4, 6), (2, 3, 6), (2, 4, 6)],[(1, 4, 5), (1, 4, 6), (2, 3, 5), (2, 3, 6)],[(1, 4, 5), (1, 4, 6), (2, 4, 5), (2, 4, 6)],[(2, 3, 5), (2, 3, 6), (2, 4, 5), (2, 4, 6)]]
for S in itertools.combinations(trip8, 6):
    if not any(set(c) <= set(S) for c in cop): print('good 6:', S)
for S in itertools.combinations(trip8, 5):
    if not any(set(c) <= set(S) for c in cop): print('good 5:', S)
